import {H3} from '@jetbrains/ring-ui-built/components/heading/heading'
import {IconButton} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import {Suspense, useCallback} from 'react'

import {useAppSelector} from '../../../../../../../hooks/react-redux'
import {getBuild} from '../../../../../../../selectors'
import {StatusBadge, TimeBadge as AdvancedTimeBadge} from '../../../../../../common/Badges'
import {EntityType} from '../../../../../../common/Badges/StatusBadge/StatusBadge.consts'
import {useDurationInfo} from '../../../../../../common/Badges/TimeBadge/TimeBadge.hooks'
import BuildLogBuildNavigationWrapper from '../../../../../../packages/BuildLog/FullBuildLog/BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper'
import {SELECTED_BUILD_DEPENDENCY_ID_PARAM} from '../../../../../../packages/BuildLog/FullBuildLog/BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper.consts'
import {AgentBadge} from '../../../../components/Badges'
import ReusedJobStatusLink from '../../../../components/ReusedJobStatusLink/ReusedJobStatusLink'

import {useJobDetailsHeader, useParallelizedJobDetailsHeader} from './JobDetailsHeader.hooks'

import styles from './JobDetailsHeader.module.css'

import {useBooleanQueryParamState, useQueryParam} from 'src/hooks/routes'
import {getHrefWithQueryParams} from 'src/routes'
import type {BuildId} from 'src/types'
import {toBuildId} from 'src/types'

type Props = {
  className?: string
  jobId: BuildId
}

function JobDetailsHeader({className, jobId}: Props) {
  const parallelized = useAppSelector(state => getBuild(state, jobId)?.parallelized)
  const pageFullLogBuildIdParam = useQueryParam(SELECTED_BUILD_DEPENDENCY_ID_PARAM)
  const selectedNavigationId =
    pageFullLogBuildIdParam != null ? toBuildId(pageFullLogBuildIdParam) : null

  const [isJobDetailsFullscreen, setJobDetailsFullscreen] = useBooleanQueryParamState(
    'jobDetailsFullscreen',
    false,
  )

  const {navigate, location, jobName, jobStatus, isJobRunning, isJobReused} =
    useJobDetailsHeader(jobId)
  const {batchJobStatus, isBatchJobRunning} = useParallelizedJobDetailsHeader(selectedNavigationId)

  const toggleFullscreen = useCallback(() => {
    setJobDetailsFullscreen(!isJobDetailsFullscreen, true)
  }, [isJobDetailsFullscreen, setJobDetailsFullscreen])

  const closeSidebar = useCallback(() => {
    const href = getHrefWithQueryParams(location, null, () => ({}))
    navigate(href, {replace: true, preventScrollReset: true})
  }, [location, navigate])

  const {duration, queueDuration, estimatedDuration, isQueued, isRunning} = useDurationInfo(
    selectedNavigationId ?? jobId,
  )

  return (
    <div className={classNames(className, styles.header)}>
      <div className={styles.heading}>
        <H3>{jobName}</H3>
        {isJobReused && (
          <span className={styles.reusedLabel}>
            <ReusedJobStatusLink
              jobId={`${jobId}`}
              placeholder="Reused job"
              prefix="Job reused from "
              link
            />
          </span>
        )}
      </div>
      <div className={styles.actions}>
        {!isJobDetailsFullscreen && (
          <IconButton
            className={styles.actionButton}
            title="Enter full screen"
            icon="expand-all"
            onClick={toggleFullscreen}
          />
        )}
        <IconButton
          className={styles.actionButton}
          title="Close job sidebar"
          icon="close"
          onClick={isJobDetailsFullscreen ? toggleFullscreen : closeSidebar}
        />
      </div>
      <div className={styles.subheading}>
        <Suspense>
          {parallelized && (
            <BuildLogBuildNavigationWrapper className={styles.navigation} buildId={jobId} />
          )}
          <div className={styles.badges}>
            <StatusBadge
              status={batchJobStatus != null ? batchJobStatus : jobStatus}
              isRunning={isBatchJobRunning != null ? isBatchJobRunning : isJobRunning}
              type={EntityType.JOB}
            />
            <AdvancedTimeBadge
              buildId={selectedNavigationId ?? jobId}
              duration={duration}
              estimatedDuration={estimatedDuration}
              queueDuration={queueDuration}
              isRunning={isRunning}
              isQueued={isQueued}
              clickable={false}
            />
            <AgentBadge runId={selectedNavigationId ?? jobId} />
          </div>
        </Suspense>
      </div>
    </div>
  )
}

export default JobDetailsHeader
