import isEqual from 'lodash/isEqual'
import merge from 'lodash/merge'
import {useEffect, useMemo, useState} from 'react'

import {useAppDispatch} from '../../../../hooks/react-redux'
import type {Build} from '../../../../services/rest'
import {restApi} from '../../../../services/rest'
import type {BuildId} from '../../../../types'
import {emptyArray} from '../../../../utils/empty'
import {subscribeOnRunningBuild} from '../../../../utils/subscriber'
import {usePipelineRunArg} from '../PipelineRunPage/PipelineRunPage.hooks'

export function useJobParallelRuns(job?: Build) {
  const jobProjectInternalId = job?.buildType?.project?.internalId
  const jobSnapshotDependencies = job?.['snapshot-dependencies']?.build
  const isParallelized = job?.parallelized
  const isRunning = job?.state === 'running'
  const jobId = job?.id

  const arg = usePipelineRunArg()
  const dispatch = useAppDispatch()

  const parallelTestsRuns = useMemo(() => {
    if (!isParallelized || jobSnapshotDependencies == null) {
      return emptyArray as Build[]
    }
    return jobSnapshotDependencies.filter(
      dep => jobProjectInternalId !== dep.buildType?.project?.internalId,
    )
  }, [jobSnapshotDependencies, jobProjectInternalId, isParallelized])
  const [parallelTestsRunsIds, setParallelTestsRunsIds] = useState<BuildId[]>([])

  useEffect(() => {
    setParallelTestsRunsIds(prevState => {
      const newIds = parallelTestsRuns.map(parallelRun => parallelRun.id!)

      return isEqual(prevState, newIds) ? prevState : newIds
    })
  }, [parallelTestsRuns])

  useEffect(() => {
    if (isRunning) {
      const subscriptions = parallelTestsRunsIds.map(parallelRunId =>
        subscribeOnRunningBuild(parallelRunId, data => {
          dispatch(
            restApi.util.updateQueryData('getBuildNormalized', arg, draft => {
              const draftParallelRun = draft?.entities?.builds?.[draft?.result!]?.[
                'snapshot-dependencies'
              ]?.build
                ?.find(build => build.id === jobId)
                ?.['snapshot-dependencies']?.build?.find(build => build.id === parallelRunId)

              merge(draftParallelRun, data)
            }),
          )
        }),
      )

      return () => {
        subscriptions.forEach(unsubscribe => unsubscribe())
      }
    }
    return undefined
  }, [arg, dispatch, jobId, parallelTestsRunsIds, isRunning])

  return parallelTestsRuns
}
