import {useEffect} from 'react'
import {useLocation, useNavigate, useSearchParams} from 'react-router'

import {useQueryParam} from '../../../../../../hooks/routes'
import {useThrottle} from '../../../../../../hooks/useThrottle'
import {getSingleBuildArg} from '../../../../../../rest/builds'
import {getBuildLocator} from '../../../../../../rest/locators'
import {getBuildStatusTypeFromBuild} from '../../../../../../selectors'
import {restApi} from '../../../../../../services/rest'
import type {BuildTypeInternalId} from '../../../../../../types'
import {subscribeOnBuildTypeEvents} from '../../../../../../utils/subscriber'
import {
  BUILD_FINISHED,
  BUILD_INTERRUPTED,
  BUILD_STARTED,
  BUILD_TYPE_REMOVED_FROM_QUEUE,
} from '../../../../../../utils/subscriptionEvents'
import {getTabParamsKey} from '../../../../../../utils/tabs'
import {SELECTED_BUILD_DEPENDENCY_ID_PARAM} from '../../../../../packages/BuildLog/FullBuildLog/BuildLogBuildNavigationWrapper/BuildLogBuildNavigationWrapper.consts'
import {
  getProblemOccurrencesLocator,
  getRootNode,
} from '../../../../../packages/BuildProblems/BuildProblemsPreview/BuildProblemsPreview.utils'
import {buildProblemsTreeContextDefaultValue} from '../../../../../packages/BuildProblems/BuildProblemsTree/BuildProblemsTree.context'
import {getOwnTestsLocator} from '../../../../../packages/Tests/TestsPreviewPanel/TestsPreviewPanel.utils'
import {useTestOccurrenceTreeArg} from '../../../../../packages/Tests/TestsTree/TestsTree.hooks'
import {
  getRootTestCounters,
  getTestsLocator as getTestTreeLocator,
} from '../../../../../packages/Tests/TestsTree/TestsTree.utils'
import {usePipelineRunArg} from '../../PipelineRunPage.hooks'

const THROTTLER_TIMEOUT = 10000
function useFailedTestsAndProblems(jobId: number, headInternalId?: BuildTypeInternalId) {
  const endpoint = buildProblemsTreeContextDefaultValue.getEndpoint()
  const problemsLocator = getProblemOccurrencesLocator(jobId)
  const {problemsCount = 0, refetch: refetchProblemOccurenceTree} =
    restApi.endpoints.getProblemOccurrenceTree.useQuery(
      {
        endpoint,
        locator: problemsLocator,
        treeLocator: problemsLocator,
      },
      {
        selectFromResult: ({data}) => ({
          problemsCount: getRootNode(data?.tree.node)?.count,
        }),
      },
    )
  const fetchProblemOccurrenceTreeHandler = useThrottle(
    refetchProblemOccurenceTree,
    THROTTLER_TIMEOUT,
  )

  const testsLocator = getOwnTestsLocator(getBuildLocator(jobId))
  const testsTreeLocator = getTestTreeLocator({baseLocator: testsLocator})
  const testsArg = useTestOccurrenceTreeArg(testsTreeLocator)
  const {failedTestsCount, refetch} = restApi.endpoints.getTestOccurrenceTree.useQuery(testsArg, {
    selectFromResult: ({data}) => ({
      failedTestsCount: getRootTestCounters(data?.tree.node)?.failed ?? 0,
    }),
  })

  useEffect(
    () =>
      headInternalId
        ? subscribeOnBuildTypeEvents(
            headInternalId,
            [BUILD_TYPE_REMOVED_FROM_QUEUE, BUILD_FINISHED, BUILD_INTERRUPTED],
            () => {
              refetch()
              fetchProblemOccurrenceTreeHandler()
            },
          )
        : undefined,
    [headInternalId, fetchProblemOccurrenceTreeHandler, refetch],
  )

  return {
    problemsCount,
    failedTestsCount,
  }
}

export function useJobDetails(jobId: number) {
  const [searchParams] = useSearchParams()
  const pageFullLogBuildIdParam = useQueryParam(SELECTED_BUILD_DEPENDENCY_ID_PARAM)

  const arg = usePipelineRunArg()
  const {isPipelineFinished, projectId} = restApi.endpoints.getBuildNormalized.useQuery(arg, {
    selectFromResult: ({data}) => {
      const run = data?.entities?.builds?.[data?.result!]
      const headId = run?.buildType
      return {
        isPipelineFinished: data?.entities?.builds?.[data?.result!]?.state === 'finished',
        projectId: data?.entities?.buildTypes?.[headId!]?.project?.id,
      }
    },
  })

  const {
    areTabsLoading,
    tabs,
    refetch: refetchTabs,
  } = restApi.endpoints.getTabs.useQuery(
    {key: getTabParamsKey({buildId: jobId}), cacheTabs: true},
    {
      selectFromResult: ({isLoading, data}) => ({areTabsLoading: isLoading, tabs: data}),
    },
  )
  const location = useLocation()
  const navigate = useNavigate()
  const {headInternalId, jobStatus, isRunLoading, refetch} =
    restApi.endpoints.getBuildNormalized.useQuery(
      getSingleBuildArg(getBuildLocator(jobId), {
        withBuildTypeDetails: true,
      }),
      {
        selectFromResult: ({data, isLoading}) => {
          const run = data?.entities?.builds?.[data?.result!]
          const headId = run?.buildType
          return {
            headInternalId: data?.entities?.buildTypes?.[headId!]?.internalId,
            jobStatus: getBuildStatusTypeFromBuild(run),
            isRunLoading: isLoading,
          }
        },
      },
    )

  const {problemsCount, failedTestsCount} = useFailedTestsAndProblems(
    Number(pageFullLogBuildIdParam ?? jobId),
    headInternalId,
  )

  useEffect(
    () =>
      headInternalId
        ? subscribeOnBuildTypeEvents(
            headInternalId,
            [BUILD_TYPE_REMOVED_FROM_QUEUE, BUILD_STARTED, BUILD_FINISHED, BUILD_INTERRUPTED],
            () => {
              refetchTabs()
              refetch()
            },
          )
        : undefined,
    [headInternalId, refetch, refetchTabs],
  )

  return {
    searchParams,
    navigate,
    location,
    isPipelineFinished,
    isLoading: areTabsLoading || isRunLoading,
    tabs,
    projectId,
    headInternalId,
    jobStatus,
    problemsCount,
    failedTestsCount,
  }
}
