import merge from 'lodash/merge'
import {useEffect} from 'react'

import {useJobId} from '../../../../EditPipelinePage/EditPipelinePage.hooks'
import {useJobParallelRuns} from '../../../../hooks/useJobParallelRuns'
import {usePipelineRunArg} from '../../../PipelineRunPage.hooks'

import {isReused} from 'src/components/pages/BuildPage/DependenciesTab/DependenciesChain/DependenciesChain.utils'
import {useAppDispatch} from 'src/hooks/react-redux'
import useMyId from 'src/hooks/useMyId'
import {getBuildStatusIconFromBuild} from 'src/selectors'
import {restApi} from 'src/services/rest'
import type {BuildId, NormalizedBuild} from 'src/types'
import {subscribeOnRunningBuild} from 'src/utils/subscriber'

export function usePipelineRunJob(jobId: BuildId) {
  const arg = usePipelineRunArg()
  const {job, run} = restApi.endpoints.getBuildNormalized.useQuery(arg, {
    selectFromResult: ({data}) => {
      const run = data?.entities?.builds?.[data?.result!]

      return {
        job: run?.['snapshot-dependencies']?.build?.find(build => build.id === jobId),
        run,
      }
    },
  })
  const myId = useMyId()
  const icon = getBuildStatusIconFromBuild(job, myId, false, false, true)
  const selectedJobId = Number(useJobId())
  const isJobReused = isReused(job as NormalizedBuild, run)
  const isRunning = job?.state === 'running'
  const dispatch = useAppDispatch()
  const parallelTestsRuns = useJobParallelRuns(job)

  useEffect(() => {
    if (isRunning) {
      return subscribeOnRunningBuild(jobId, data =>
        dispatch(
          restApi.util.updateQueryData('getBuildNormalized', arg, draft => {
            const draftRun = draft?.entities?.builds?.[draft?.result!]?.[
              'snapshot-dependencies'
            ]?.build?.find(build => build.id === jobId)

            merge(draftRun, data)
          }),
        ),
      )
    }
    return undefined
  }, [arg, dispatch, jobId, isRunning])

  return {
    job,
    icon,
    isJobReused,
    selectedJobId,
    parallelTestsRuns,
  }
}
