import RunJob from '../../../../components/RunJob/RunJob'
import {usePipelineRunJobAgentCompatibilityStatus} from '../../../PipelineRunPage.hooks'

import {usePipelineRunJob} from './PipelineRunJob.hooks'

import type {BuildId} from 'src/types'

type Props = {
  x: number
  y: number
  jobId: BuildId
}

export default function PipelineRunJob({x, y, jobId}: Props) {
  const {job, icon, parallelTestsRuns, selectedJobId, isJobReused} = usePipelineRunJob(jobId)
  const runningInfo = job?.['running-info']
  const {isCurrentJobIncompatibilityAgent} = usePipelineRunJobAgentCompatibilityStatus(job)

  return (
    <RunJob
      position={{x, y}}
      jobId={jobId}
      runningInfo={runningInfo}
      isJobReused={isJobReused}
      parallelTestsRuns={parallelTestsRuns}
      selectedJobId={selectedJobId}
      icon={icon}
      isIncompatibilityAgent={isCurrentJobIncompatibilityAgent}
      to={{search: jobId === selectedJobId ? '' : `job=${jobId}`}}
      replace
      {...job}
    />
  )
}
