import {Tab, Tabs} from '@jetbrains/ring-ui-built/components/tabs/tabs'
import {Suspense} from 'react'
import type {EntryPointProps} from 'react-relay'
import {useLocation, useNavigate, useParams, useSearchParams} from 'react-router'

import {useAppSelector} from '../../../../../hooks/react-redux'
import type {QueryParam} from '../../../../../hooks/routes'
import {getHrefWithQueryParams} from '../../../../../routes'
import {getBuild} from '../../../../../selectors'
import type {Tab as TabType, TabId} from '../../../../../types'
import {toBuildId} from '../../../../../types'
import BuildArtifactsTree from '../../../../common/BuildArtifactsTree/BuildArtifactsTree'
import Loader from '../../../../common/Loader/Loader'
import type {BuildArtifactsTabEntryPoint} from '../../../BuildPage/BuildArtifactsTab/BuildArtifactsTab.entryPoint'
import type {BuildTestsTabEntryPoint} from '../../../BuildPage/BuildTestsTab/BuildTestsTab.entryPoint'
import {PipelineRunTabs, pipelineRunTabs} from '../PipelineRunPage.consts'
import type {ChangesTabEntryPoint} from '../PipelineTab/JobDetails/ChangesTab/ChangesTab.entryPoint'
import {JobGameTabContextContext} from '../PipelineTab/JobDetails/GameTab/GameTab.contexts'
import {useJobGameTabContextValue} from '../PipelineTab/JobDetails/GameTab/GameTab.hooks'
import type {OverviewTabEntryPoint} from '../PipelineTab/JobDetails/OverviewTab/OverviewTab.entryPoint'
import PipelineTab from '../PipelineTab/PipelineTab'

import styles from './PipelineRunContent.module.css'

export type NestedEntryPoints = {
  testsTab?: typeof BuildTestsTabEntryPoint
  artifactsTab?: typeof BuildArtifactsTabEntryPoint
  changesTab?: typeof ChangesTabEntryPoint
  overviewTab?: typeof OverviewTabEntryPoint
}
type Props = {
  jobId?: QueryParam
}
function PipelineRunContent({
  entryPoints,
  props: {jobId},
}: EntryPointProps<{}, NestedEntryPoints, Props, {}>) {
  const navigate = useNavigate()
  const location = useLocation()
  const [searchParams] = useSearchParams()
  const jobGameTabContextValue = useJobGameTabContextValue()
  const selectedTab = searchParams.get('pipelineRunTab') ?? pipelineRunTabs[0]?.id
  const {pipelineRunId = ''} = useParams()
  const pipelineRunIdNumber = toBuildId(pipelineRunId)
  const buildType = useAppSelector(state => getBuild(state, pipelineRunIdNumber)?.buildType)

  const renderTabContent = (tabId: TabId) => {
    if (tabId === PipelineRunTabs.PIPELINE) {
      return (
        <JobGameTabContextContext.Provider value={jobGameTabContextValue}>
          <PipelineTab jobId={jobId != null ? toBuildId(jobId) : null} entryPoints={entryPoints} />
        </JobGameTabContextContext.Provider>
      )
    }

    if (tabId === PipelineRunTabs.ARTIFACTS) {
      if (pipelineRunIdNumber == null) {
        return null
      }
      return (
        <div className={styles.artifactsTabWrapper}>
          <BuildArtifactsTree
            buildId={pipelineRunIdNumber}
            buildType={buildType}
            showDownloadLink
            level={0}
            compact={false}
          />
        </div>
      )
    }

    return null
  }

  const renderTab = (tab: TabType) => {
    const href = getHrefWithQueryParams(location, null, params => ({
      ...params,
      pipelineRunTab: tab.id,
    }))
    return (
      <Tab
        key={tab.id}
        id={tab.id}
        title={tab.title}
        href={href}
        titleProps={{
          onPlainLeftClick: () =>
            navigate(href, {replace: selectedTab === tab.id, preventScrollReset: true}),
        }}
      >
        <div className={styles.tabContent}>
          <Suspense fallback={<Loader />}>{renderTabContent(tab.id)}</Suspense>
        </div>
      </Tab>
    )
  }

  const renderTabs = () => (
    <Tabs className={styles.pipelineTabs} selected={selectedTab}>
      {pipelineRunTabs.map(renderTab)}
    </Tabs>
  )

  return pipelineRunTabs.length > 1 ? renderTabs() : renderTab(pipelineRunTabs[0])
}

export type PipelineRunContentComponent = typeof PipelineRunContent

export default PipelineRunContent
