import {useMemo} from 'react'

import type {Build} from '../../../../../../services/rest'
import {restApi} from '../../../../../../services/rest'
import {emptyArray} from '../../../../../../utils/empty'
import Loader from '../../../../../common/Loader/Loader'
import PipelineChart from '../../../components/PipelineChart/PipelineChart'
import {createGraph} from '../../../utils/graph'
import {usePipelineRunArg} from '../../PipelineRunPage.hooks'

import PipelineRunJob from './PipelineRunJob/PipelineRunJob'

const NODE_HEIGHT = 88
const NODE_WIDTH = 192
const GAP_HORIZONTAL = 32
const GAP_VERTICAL = 16

export default function PipelineRunChart() {
  const arg = usePipelineRunArg()
  const {dependencies} = restApi.endpoints.getBuildNormalized.useQuery(arg, {
    selectFromResult: ({data}) => {
      const run = data?.entities?.builds?.[data?.result!]
      return {
        dependencies: run?.['snapshot-dependencies']?.build ?? emptyArray,
      }
    },
  })
  const graph = useMemo(
    () =>
      createGraph<Build>({
        data: dependencies,
        getId: build => String(build.id),
        getDependencies: build =>
          build['snapshot-dependencies']?.build?.map(dep => String(dep.id)) ?? emptyArray,
      }),
    [dependencies],
  )
  return dependencies.length > 0 ? (
    <PipelineChart
      graph={graph}
      nodeWidth={NODE_WIDTH}
      nodeHeight={NODE_HEIGHT}
      gapHorizontal={GAP_HORIZONTAL}
      gapVertical={GAP_VERTICAL}
      renderJob={({data, x, y}) => (
        <PipelineRunJob
          x={x! - NODE_HEIGHT / 2 - GAP_VERTICAL / 2}
          y={y! - NODE_WIDTH / 2 - GAP_HORIZONTAL / 2}
          jobId={Number(data.id)}
          key={data.id}
        />
      )}
    />
  ) : (
    <Loader />
  )
}
