import {Anchor} from '@jetbrains/ring-ui-built/components/dropdown/dropdown'
import Link from '@jetbrains/ring-ui-built/components/link/link'
import classNames from 'classnames'
import * as React from 'react'
import type {HTMLAttributes} from 'react'

import {stringifyId} from '../../../types'
import type {BuildId} from '../../../types'
import {BS} from '../../../types/BS_types'
import {noop} from '../../../utils/empty'
import PopupControl from '../../classic/PopupControl/PopupControl'

import styles from './CompatibleAgents.module.css'

const Popup = BS?.AgentInfoPopup
const hidePopupCommand = Popup ? () => Popup.hidePopup() : noop
const stopHidingPopupCommand = Popup ? () => Popup.stopHidingPopup() : noop
type DefaultProps = {
  secondary: boolean
}
type Props = DefaultProps & {
  className?: string
  label: string
  baseHref?: string | null | undefined
  buildId: BuildId
  buildUrl?: string | null | undefined
  wrapperProps?: HTMLAttributes<HTMLSpanElement>
  withAnchor?: boolean
}
export default class CompatibleAgents extends React.PureComponent<Props> {
  static defaultProps: DefaultProps = {
    secondary: false,
  }

  showPopupCommand: (event: React.SyntheticEvent<HTMLSpanElement> | Event) => unknown = Popup
    ? e => {
        if (e.currentTarget != null) {
          Popup.showAgentsPopup(e.currentTarget, this.props.buildId)
        }
      }
    : noop

  render() {
    const {className, label, baseHref, buildId, secondary, wrapperProps, withAnchor} = this.props
    const classes = classNames(className, styles.compatibleAgents)
    const linkClasses = classNames({
      [styles.secondary]: secondary,
    })

    if (withAnchor) {
      return (
        <Anchor
          className={classNames(styles.anchor, {[styles.secondary]: secondary}, className)}
          onClick={this.showPopupCommand}
        >
          {label}
        </Anchor>
      )
    }
    return (
      <PopupControl
        wrapperProps={wrapperProps}
        className={classes}
        showPopupCommand={this.showPopupCommand}
        hidePopupCommand={hidePopupCommand}
        stopHidingPopupCommand={stopHidingPopupCommand}
        controlId={`compatibleAgents:${stringifyId(buildId)}`}
      >
        <Link href={baseHref != null ? `${baseHref}` : undefined} className={linkClasses}>
          {label}
        </Link>
      </PopupControl>
    )
  }
}
